        vi=ci.value; vg=cg.value
        def norm(v):
            if hasattr(v,'text'): return ('AF', v.text, v.ref)
            return v
        ni=norm(vi); ng=norm(vg)
        if ni!=ng:
            diffs.append((ci.coordinate, ni, ng))
        # compare style
        if ci.number_format != cg.number_format:
            diffs.append((ci.coordinate,'numfmt',ci.number_format,cg.number_format))
        # fill
        fi=ci.fill; fg=cg.fill
        if ci.fill.fill_type != cg.fill.fill_type:
            diffs.append((ci.coordinate,'filltype',ci.fill.fill_type,cg.fill.fill_type))
