        for side in ['left','right','top','bottom']:
            if getattr(ci.border, side).style != getattr(cg.border, side).style:
                diffs.append((ci.coordinate,'border'+side,getattr(ci.border,side).style,getattr(cg.border,side).style))
print('num diffs', len(diffs))
